--
-- Threads (slug — target libraries):
--   1. isaiah-44-i-will-pour-my-spirit-upon-thy-seed — NT (Acts 2, John 7) + Tanakh (Joel 2) [free]
--      (★★ the Spirit poured on the seed/offspring = the two-house posterity; Shavuot fulfillment)
--   2. isaiah-44-i-am-the-first-and-i-am-the-last — NT (Revelation 1, 22) + Tanakh (Isaiah 48 lateral) [free]
--      (★★ the risen Messiah bears Yahuah's own title — the Formed Son who is Yahuah and has a Father)
--   3. isaiah-44-they-that-make-a-graven-image-are-vanity — NT (Romans 1) + Tanakh (Psalm 115, 135, Jeremiah 10) [free]
--      (★★ the idol-maker folly; Yahuah FORMS, the idolater only fashions a dead block — Formed vs formed-by-hands)
--   4. isaiah-44-i-have-blotted-out-thy-transgressions-return-unto-me — NT (Acts 3) + Tanakh (Psalm 103) [free]
--      (★ pardon UNTO return/teshuvah; redemption-unto-obedience, not license)
--   5. isaiah-44-cyrus-he-is-my-shepherd — Tanakh (Isaiah 45, Ezra 1) [free]
--      (★ Cyrus foretold by name; the pagan king raised as Yahuah's instrument to free the captives to rebuild)
--
-- Framing notes:
--   ★★ THE SPIRIT ON THE SEED (THREAD 1): *I will pour water upon him that is thirsty, and floods upon
--      the dry ground: I will pour my spirit upon thy seed, and my blessing upon thine offspring* (44:3).
--      The seed/offspring is the two-house posterity, and the outpouring is Joel's promise — *I will pour
--      out my spirit upon all flesh; and your sons and your daughters shall prophesy* (Joel 2:28) — which
--      Acts declares fulfilled at Shavuot: *I will pour out of my Spirit upon all flesh* (Acts 2:17). The
--      living water is the Spirit Yahusha names at the feast: *If any man thirst, let him come unto me,
--      and drink... out of his belly shall flow rivers of living water* (John 7:37-38), *this spake he of
--      the Spirit* (7:39). One outpouring on the seed of promise.
--   ★★ THE FIRST AND THE LAST (THREAD 2): *I am the first, and I am the last; and beside me there is no
--      Elohim (God)* (44:6) — and Isaiah's sister word *I am he; I am the first, I also am the last*
--      (48:12). The risen Messiah claims that very title: *Fear not; I am the first and the last*
--      (Revelation 1:17); *I am Alpha and Omega... the Almighty* (1:8); *I am Alpha and Omega... the first
--      and the last* (22:13). The Formed Son bears Yahuah's own self-title — he IS Yahuah and HAS a
--      Father; the Formed and the Formless, never co-equal trinitarian persons. (The ch48 NT thread is
--      already built; this is the cross-lateral, a distinct isaiah-44- thread, NOT a duplicate.)
--   ★★ THE IDOL-MAKER FOLLY (THREAD 3): the carpenter and the smith fashion a god with hammer and rule
--      (44:12-13), and the man *heweth him down cedars... he burneth part thereof in the fire... and the
--      residue thereof he maketh a god, even his graven image: he falleth down unto it, and worshippeth
--      it, and prayeth unto it, and saith, Deliver me; for thou art my god* (44:14-17). Yahuah FORMS (44:2,
--      44:24); the idolater only fashions a dead block. The Psalms expose the lifelessness — *eyes have
--      they, but they see not* (Psalm 115:5); *the idols of the heathen are silver and gold, the work of
--      men's hands* (Psalm 135:15) — and Jeremiah: *every founder is confounded by the graven image... no
--      breath in them* (Jeremiah 10:14). Paul names the exchange: *changed the glory of the uncorruptible
--      Elohim (God) into an image* (Romans 1:23). The 44:20 punchline (*a lie in his right hand*) belongs
--      to the existing thread; this one centers on the making (44:9-19).
--   ★ BLOTTED OUT UNTO RETURN (THREAD 4): *I have blotted out, as a thick cloud, thy transgressions, and,
--      as a cloud, thy sins: return unto me; for I have redeemed thee* (44:22). The pardon is UNTO
--      teshuvah — *Repent ye therefore, and be converted, that your sins may be blotted out* (Acts 3:19);
--      *so far hath he removed our transgressions from us* (Psalm 103:12). Redemption-unto-obedience, not
--      license; the blotting-out summons the return.
--   ★ CYRUS MY SHEPHERD (THREAD 5): *that saith of Cyrus, He is my shepherd, and shall perform all my
--      pleasure: even saying to Jerusalem, Thou shalt be built; and to the temple, Thy foundation shall be
--      laid* (44:28). The pagan king is named generations before, raised as Yahuah's instrument — *to his
--      anointed, to Cyrus, whose right hand I have holden* (Isaiah 45:1); *he shall build my city, and he
--      shall let go my captives* (45:13) — and history records it: *Yahuah (LORD) stirred up the spirit of
--      Cyrus... to build him an house at Jerusalem* (Ezra 1:1-2). Yahuah confirms his servant's word and
--      moves even a heathen king to free the captives to rebuild.
--   VERSES WITH NO ADD: v.20 (left to the PRE-EXISTING 44:20 idol-deception thread; cited only in passing
--      prose). All other verses recorded above and woven; none silently skipped.

CREATE TEMP VIEW _s303_isa44_lookup AS
SELECT e.slug AS edition_slug, b.slug AS book_slug, c.chapter_number, v.verse_number, v.id AS verse_id
  FROM verses v JOIN chapters c ON v.chapter_id=c.id JOIN books b ON c.book_id=b.id
  JOIN editions e ON b.edition_id=e.id
 WHERE e.slug IN ('canon','enoch','jubilees','jasher','apocrypha','apocrypha-charles-vol1','pseudepigrapha','adam-eve-conflict','apocalypse-of-abraham','ascension-isaiah','sonnini-acts-29');

INSERT INTO cross_references (source_verse_id, target_verse_id, source, note, tier_required)
SELECT sv.verse_id, tv.verse_id, 'manual', i.note, i.tier::content_tier
  FROM (VALUES
    -- THREAD 1 (★★): I will pour my spirit upon thy seed (the Spirit on the two-house posterity)
    ('canon','isaiah',44,3,'canon','joel',2,28,'free',
      E'*And it shall come to pass afterward, that I will pour out my spirit upon all flesh; and your sons and your daughters shall prophesy, your old men shall dream dreams, your young men shall see visions* (Joel 2:28). The promise *I will pour my spirit upon thy seed, and my blessing upon thine offspring* (Isaiah 44:3) is Joel''s very word — the Spirit *poured out* on the posterity. The water on the thirsty and the floods on the dry ground is the Ruach HaKodesh (Holy Spirit) given to the seed of promise.'),
    ('canon','isaiah',44,3,'canon','joel',2,29,'free',
      E'*And also upon the servants and upon the handmaids in those days will I pour out my spirit* (Joel 2:29). The outpouring *upon thy seed... upon thine offspring* (Isaiah 44:3) reaches even the servants and handmaids — none of the covenant household left out. The blessing on the offspring is the Spirit poured on the whole two-house posterity.'),
    ('canon','isaiah',44,3,'canon','acts',2,17,'free',
      E'*And it shall come to pass in the last days, saith Elohim (God), I will pour out of my Spirit upon all flesh: and your sons and your daughters shall prophesy, and your young men shall see visions, and your old men shall dream dreams* (Acts 2:17). At Shavuot the *pour my spirit upon thy seed* (Isaiah 44:3) is declared fulfilled — *this is that which was spoken by the prophet Joel* (Acts 2:16). The appointed time of Weeks is the day the Spirit falls on the offspring.'),
    ('canon','isaiah',44,3,'canon','acts',2,18,'free',
      E'*And on my servants and on my handmaidens I will pour out in those days of my Spirit; and they shall prophesy* (Acts 2:18). The blessing *upon thine offspring* (Isaiah 44:3) is poured without partiality — servants and handmaidens prophesy. The seed of promise receives the Spirit Yahuah pledged to pour.'),
    ('canon','isaiah',44,3,'canon','john',7,38,'free',
      E'*He that believeth on me, as the scripture hath said, out of his belly shall flow rivers of living water* (John 7:38). The *water upon him that is thirsty, and floods upon the dry ground* (Isaiah 44:3) is named living water at the feast: *If any man thirst, let him come unto me, and drink* (John 7:37). The thirsty ground watered is the seed receiving the Spirit.'),
    ('canon','isaiah',44,3,'canon','john',7,39,'free',
      E'*(But this spake he of the Spirit, which they that believe on him should receive: for the Ruach HaKodesh (Holy Spirit) was not yet given; because that Yahusha (Jesus) was not yet glorified.)* (John 7:39). The rivers of living water are named plainly: *the Spirit*. So the *I will pour my spirit upon thy seed* (Isaiah 44:3) and the floods on the dry ground are one and the same outpouring — the Ruach HaKodesh given to those who believe.'),

    -- THREAD 2 (★★): I am the first, and I am the last (the Formed Son bears Yahuah's own title)
    ('canon','isaiah',44,6,'canon','revelation',1,17,'free',
      E'*And when I saw him, I fell at his feet as dead. And he laid his right hand upon me, saying unto me, Fear not; I am the first and the last* (Revelation 1:17). The risen Messiah claims Yahuah''s own self-title from *I am the first, and I am the last; and beside me there is no Elohim (God)* (Isaiah 44:6). The Formed Son bears the Name and the title — he IS Yahuah and HAS a Father; the Formed drawn from the Formless, never co-equal persons.'),
    ('canon','isaiah',44,6,'canon','revelation',1,8,'free',
      E'*I am Alpha and Omega, the beginning and the ending, saith Yahuah (Lord), which is, and which was, and which is to come, the Almighty* (Revelation 1:8). *I am the first, and I am the last* (Isaiah 44:6) is spoken again as Alpha and Omega — the One *which was, and is, and is to come*. Beside him there is no Elohim; the title is Yahuah''s own, borne by the Formed Son.'),
    ('canon','isaiah',44,6,'canon','revelation',22,13,'free',
      E'*I am Alpha and Omega, the beginning and the end, the first and the last* (Revelation 22:13). The seal of the whole library repeats *I am the first, and I am the last* (Isaiah 44:6) — first and last, beginning and end. The redeemer Yahuah Tseva''ot (LORD of hosts) and the One on the throne speak with one voice; the Formed Son is Yahuah and has a Father.'),
    ('canon','isaiah',44,6,'canon','isaiah',48,12,'free',
      E'*Hearken unto me, O Jacob and Yashar''el (Israel), my called; I am he; I am the first, I also am the last* (Isaiah 48:12). Isaiah''s own sister word doubles the claim of *I am the first, and I am the last; and beside me there is no Elohim (God)* (Isaiah 44:6). The redeemer who made and formed his people is the First and the Last — the title the risen Messiah takes up; one voice across the prophet.'),

    -- THREAD 3 (★★): They that make a graven image are vanity (the idol-maker folly; Former vs formed-by-hands)
    ('canon','isaiah',44,9,'canon','psalms',115,5,'free',
      E'*They have mouths, but they speak not: eyes have they, but they see not* (Psalm 115:5). *They that make a graven image are all of them vanity... they see not, nor know* (Isaiah 44:9) — the made-thing is blind and dumb, as the Psalm exposes: *their idols are silver and gold, the work of men''s hands* (Psalm 115:4). The carpenter''s god has eyes that cannot see; Yahuah forms, the idol is fashioned dead.'),
    ('canon','isaiah',44,17,'canon','psalms',115,7,'free',
      E'*They have hands, but they handle not: feet have they, but they walk not: neither speak they through their throat* (Psalm 115:7). The man *falleth down unto it, and worshippeth it, and prayeth unto it, and saith, Deliver me; for thou art my god* (Isaiah 44:17) — yet the thing he begs cannot move or speak. *They that make them are like unto them* (Psalm 115:8); the worshipper of a dead block deceives himself.'),
    ('canon','isaiah',44,15,'canon','psalms',135,15,'free',
      E'*The idols of the heathen are silver and gold, the work of men''s hands* (Psalm 135:15). The man *kindleth it, and baketh bread; yea, he maketh a god, and worshippeth it; he maketh it a graven image, and falleth down thereto* (Isaiah 44:15) — the very wood he cooks with becomes his god. The idol is nothing but the work of men''s hands; Yahuah alone is Maker.'),
    ('canon','isaiah',44,18,'canon','psalms',135,16,'free',
      E'*They have mouths, but they speak not; eyes have they, but they see not* (Psalm 135:16). *They have not known nor understood: for he hath shut their eyes, that they cannot see* (Isaiah 44:18) — the maker is as blind as the thing he made. The eyes that cannot see belong to both the idol and the one who bows to it.'),
    ('canon','isaiah',44,12,'canon','jeremiah',10,14,'free',
      E'*Every man is brutish in his knowledge: every founder is confounded by the graven image: for his molten image is falsehood, and there is no breath in them* (Jeremiah 10:14). The smith who *worketh in the coals, and fashioneth it with hammers* (Isaiah 44:12) is the founder Jeremiah names confounded — his molten image *is falsehood, and there is no breath in them*. The fashioned god has no life; the Former alone gives breath.'),
    ('canon','isaiah',44,9,'canon','romans',1,22,'free',
      E'*Professing themselves to be wise, they became fools* (Romans 1:22). *They that make a graven image are all of them vanity... they see not, nor know; that they may be ashamed* (Isaiah 44:9) — the very folly Paul names: men who *professing themselves to be wise* became fools. The idol-maker''s wisdom is shame.'),
    ('canon','isaiah',44,17,'canon','romans',1,23,'free',
      E'*And changed the glory of the uncorruptible Elohim (God) into an image made like to corruptible man, and to birds, and fourfooted beasts, and creeping things* (Romans 1:23). When the man *maketh it after the figure of a man... and the residue thereof he maketh a god* (Isaiah 44:13,17), he does what Paul indicts: he *changed the glory of the uncorruptible Elohim (God) into an image*. The Former is traded for the formed-by-hands.'),

    -- THREAD 4 (★): I have blotted out thy transgressions; return unto me (pardon unto teshuvah)
    ('canon','isaiah',44,22,'canon','acts',3,19,'free',
      E'*Repent ye therefore, and be converted, that your sins may be blotted out, when the times of refreshing shall come from the presence of Yahuah (Lord)* (Acts 3:19). The pardon *I have blotted out, as a thick cloud, thy transgressions... return unto me* (Isaiah 44:22) is the same summons — the blotting-out is UNTO turning back: *Repent ye therefore, and be converted, that your sins may be blotted out*. Redemption draws the return; it does not license the sin.'),
    ('canon','isaiah',44,22,'canon','psalms',103,12,'free',
      E'*As far as the east is from the west, so far hath he removed our transgressions from us* (Psalm 103:12). *I have blotted out, as a thick cloud, thy transgressions, and, as a cloud, thy sins* (Isaiah 44:22) — the transgressions wiped away like a vanishing cloud, removed as far as east from west. The redeemed are summoned home: *return unto me; for I have redeemed thee*.'),

    -- THREAD 5 (★): Cyrus, He is my shepherd (the pagan king raised as Yahuah's instrument)
    ('canon','isaiah',44,28,'canon','isaiah',45,1,'free',
      E'*Thus saith Yahuah (LORD) to his anointed, to Cyrus, whose right hand I have holden, to subdue nations before him* (Isaiah 45:1). *That saith of Cyrus, He is my shepherd, and shall perform all my pleasure* (Isaiah 44:28) names him; the next breath calls him *his anointed*, whose right hand Yahuah holds. The pagan king is the deliverer-type Yahuah raises and steers.'),
    ('canon','isaiah',44,28,'canon','isaiah',45,13,'free',
      E'*I have raised him up in righteousness, and I will direct all his ways: he shall build my city, and he shall let go my captives, not for price nor reward, saith Yahuah Tseva''ot (LORD of hosts)* (Isaiah 45:13). *Even saying to Jerusalem, Thou shalt be built; and to the temple, Thy foundation shall be laid* (Isaiah 44:28) is fulfilled in this: Cyrus *shall build my city, and he shall let go my captives*. Yahuah raises a heathen king to free the captives to rebuild.'),
    ('canon','isaiah',44,28,'canon','ezra',1,1,'free',
      E'*Now in the first year of Cyrus king of Persia, that the word of Yahuah (LORD) by the mouth of Jeremiah might be fulfilled, Yahuah (LORD) stirred up the spirit of Cyrus king of Persia... that he made a proclamation throughout all his kingdom* (Ezra 1:1). The word *that saith of Cyrus, He is my shepherd* (Isaiah 44:28) comes to pass: *Yahuah (LORD) stirred up the spirit of Cyrus*. The prophecy spoken generations before is recorded fulfilled to the letter.'),
    ('canon','isaiah',44,28,'canon','ezra',1,2,'free',
      E'*Thus saith Cyrus king of Persia, Yahuah Elohim (The LORD God) of heaven hath given me all the kingdoms of the earth; and he hath charged me to build him an house at Jerusalem, which is in Yahudah (Judah)* (Ezra 1:2). The decree answers *to the temple, Thy foundation shall be laid* (Isaiah 44:28) — Cyrus himself charged to *build him an house at Jerusalem*. The named king does exactly what Yahuah foretold: he sends the captives home to rebuild.')
  ) AS i(src_edition,src_slug,src_ch,src_v,tgt_edition,tgt_slug,tgt_ch,tgt_v,tier,note)
  JOIN _s303_isa44_lookup sv ON sv.edition_slug=i.src_edition AND sv.book_slug=i.src_slug AND sv.chapter_number=i.src_ch AND sv.verse_number=i.src_v
  JOIN _s303_isa44_lookup tv ON tv.edition_slug=i.tgt_edition AND tv.book_slug=i.tgt_slug AND tv.chapter_number=i.tgt_ch AND tv.verse_number=i.tgt_v
 WHERE sv.verse_id <> tv.verse_id
ON CONFLICT (source_verse_id, target_verse_id, source) DO NOTHING;

-- THREAD 1 (★★)
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'isaiah-44-i-will-pour-my-spirit-upon-thy-seed',
       E'I will pour my spirit upon thy seed — the Spirit on the two-house posterity',
       E'To Jacob his servant, Yashar''el whom he has chosen (44:1), Yahuah pledges an outpouring: *For I will pour water upon him that is thirsty, and floods upon the dry ground: I will pour my spirit upon thy seed, and my blessing upon thine offspring* (Isaiah 44:3); *and they shall spring up as among the grass, as willows by the water courses* (44:4). The seed and the offspring are the posterity of the covenant people — the two-house line — and the outpouring is Joel''s very promise: *I will pour out my spirit upon all flesh; and your sons and your daughters shall prophesy, your old men shall dream dreams, your young men shall see visions* (Joel 2:28); *and also upon the servants and upon the handmaids in those days will I pour out my spirit* (Joel 2:29). At the feast of Weeks (Shavuot) it falls, and Acts names it fulfilled: *this is that which was spoken by the prophet Joel... I will pour out of my Spirit upon all flesh* (Acts 2:16-17); *and on my servants and on my handmaidens I will pour out in those days of my Spirit* (Acts 2:18). And the living water is the same Spirit Yahusha proclaims at the feast: *If any man thirst, let him come unto me, and drink. He that believeth on me, as the scripture hath said, out of his belly shall flow rivers of living water* (John 7:37-38) — *this spake he of the Spirit* (John 7:39). One outpouring: the thirsty ground watered, the seed of promise filled with the Ruach HaKodesh (Holy Spirit).',
       sv.verse_id, ev.verse_id, 'free', 27075
  FROM _s303_isa44_lookup sv, _s303_isa44_lookup ev
 WHERE sv.edition_slug='canon' AND sv.book_slug='isaiah' AND sv.chapter_number=44 AND sv.verse_number=3
   AND ev.edition_slug='canon' AND ev.book_slug='isaiah' AND ev.chapter_number=44 AND ev.verse_number=5
ON CONFLICT (slug) DO NOTHING;

-- THREAD 2 (★★)
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'isaiah-44-i-am-the-first-and-i-am-the-last',
       E'I am the first, and I am the last — the title the risen Messiah takes up',
       E'The redeemer of Yashar''el speaks his own name: *Thus saith Yahuah (LORD) the King of Yashar''el (Israel), and his redeemer Yahuah Tseva''ot (LORD of hosts); I am the first, and I am the last; and beside me there is no Elohim (God)* (Isaiah 44:6). Isaiah''s sister word doubles it: *I am he; I am the first, I also am the last* (Isaiah 48:12). This title — first and last, beside whom there is no Elohim — is claimed by the risen Messiah in his own mouth: *Fear not; I am the first and the last* (Revelation 1:17); *I am Alpha and Omega, the beginning and the ending, saith Yahuah (Lord), which is, and which was, and which is to come, the Almighty* (Revelation 1:8); and the seal of the whole book, *I am Alpha and Omega, the beginning and the end, the first and the last* (Revelation 22:13). This is the Formed and the Formless precisely held: the One who appeared, who bears Yahuah''s own self-title, who is Yahuah — and who HAS a Father. Not two co-equal trinitarian persons, not a modalist collapse: the Formed Son, the expressed Word drawn from the Formless, speaks the redeemer''s name as his own. (The matching ch48 thread is already woven; this is the cross-lateral from 44:6.)',
       sv.verse_id, ev.verse_id, 'free', 27078
  FROM _s303_isa44_lookup sv, _s303_isa44_lookup ev
 WHERE sv.edition_slug='canon' AND sv.book_slug='isaiah' AND sv.chapter_number=44 AND sv.verse_number=6
   AND ev.edition_slug='canon' AND ev.book_slug='isaiah' AND ev.chapter_number=44 AND ev.verse_number=6
ON CONFLICT (slug) DO NOTHING;

-- THREAD 3 (★★)
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'isaiah-44-they-that-make-a-graven-image-are-vanity',
       E'They that make a graven image are vanity — the Former and the formed-by-hands',
       E'Yahuah *made thee, and formed thee from the womb* (44:2) and *stretcheth forth the heavens alone* (44:24) — the LIVING Maker. Against him stands the man who only fashions a dead block: *They that make a graven image are all of them vanity... they see not, nor know; that they may be ashamed* (Isaiah 44:9). The chapter walks the absurdity step by step — the smith *worketh in the coals, and fashioneth it with hammers* (44:12); the carpenter *maketh it after the figure of a man, according to the beauty of a man* (44:13); a man *heweth him down cedars*, plants an ash the rain nourishes (44:14), then *will take thereof, and warm himself... and baketh bread; yea, he maketh a god, and worshippeth it* (44:15); *he burneth part thereof in the fire... and the residue thereof he maketh a god, even his graven image: he falleth down unto it, and worshippeth it, and prayeth unto it, and saith, Deliver me; for thou art my god* (44:16-17). The Psalms strip the thing bare: *their idols are silver and gold, the work of men''s hands. They have mouths, but they speak not: eyes have they, but they see not... They have hands, but they handle not* (Psalm 115:4-7); *the idols of the heathen are silver and gold, the work of men''s hands... eyes have they, but they see not* (Psalm 135:15-16). Jeremiah names the lifelessness: *every founder is confounded by the graven image: for his molten image is falsehood, and there is no breath in them* (Jeremiah 10:14). And Paul indicts the exchange: *Professing themselves to be wise, they became fools* (Romans 1:22), who *changed the glory of the uncorruptible Elohim (God) into an image made like to corruptible man* (Romans 1:23). The Former who breathes life is traded for a block that cannot see. (The punchline — *a deceived heart hath turned him aside... a lie in his right hand* (44:20) — is carried by its own thread; this one centers on the making.)',
       sv.verse_id, ev.verse_id, 'free', 27081
  FROM _s303_isa44_lookup sv, _s303_isa44_lookup ev
 WHERE sv.edition_slug='canon' AND sv.book_slug='isaiah' AND sv.chapter_number=44 AND sv.verse_number=9
   AND ev.edition_slug='canon' AND ev.book_slug='isaiah' AND ev.chapter_number=44 AND ev.verse_number=19
ON CONFLICT (slug) DO NOTHING;

-- THREAD 4 (★)
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'isaiah-44-i-have-blotted-out-thy-transgressions-return-unto-me',
       E'I have blotted out thy transgressions; return unto me — pardon unto teshuvah',
       E'After the idol-folly comes the redeemer''s call to his own: *Remember these, O Jacob and Yashar''el (Israel); for thou art my servant: I have formed thee; thou art my servant: O Yashar''el (Israel), thou shalt not be forgotten of me* (Isaiah 44:21). Then the pardon: *I have blotted out, as a thick cloud, thy transgressions, and, as a cloud, thy sins: return unto me; for I have redeemed thee* (44:22). The blotting-out is not the end but the summons — it is UNTO the return. Peter preaches the same order: *Repent ye therefore, and be converted, that your sins may be blotted out, when the times of refreshing shall come from the presence of Yahuah (Lord)* (Acts 3:19) — repentance and the blotting-out bound together. And the Psalm measures the distance the pardoned sin is carried: *As far as the east is from the west, so far hath he removed our transgressions from us* (Psalm 103:12). This is redemption-unto-obedience, never license: *return unto me; for I have redeemed thee*. The pardon is the ground of the turning-back, and the chapter answers with song — *break forth into singing, ye mountains... for Yahuah (LORD) hath redeemed Jacob, and glorified himself in Yashar''el (Israel)* (44:23).',
       sv.verse_id, ev.verse_id, 'free', 27084
  FROM _s303_isa44_lookup sv, _s303_isa44_lookup ev
 WHERE sv.edition_slug='canon' AND sv.book_slug='isaiah' AND sv.chapter_number=44 AND sv.verse_number=21
   AND ev.edition_slug='canon' AND ev.book_slug='isaiah' AND ev.chapter_number=44 AND ev.verse_number=23
ON CONFLICT (slug) DO NOTHING;

-- THREAD 5 (★)
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'isaiah-44-cyrus-he-is-my-shepherd',
       E'Cyrus, He is my shepherd — the pagan king named to free the captives to rebuild',
       E'The chapter closes with a prophecy so specific it names a king not yet born. Yahuah, *that confirmeth the word of his servant, and performeth the counsel of his messengers; that saith to Jerusalem, Thou shalt be inhabited; and to the cities of Yahudah (Judah), Ye shall be built* (Isaiah 44:26), is the One *that saith of Cyrus, He is my shepherd, and shall perform all my pleasure: even saying to Jerusalem, Thou shalt be built; and to the temple, Thy foundation shall be laid* (44:28). The next chapter calls him by title: *Thus saith Yahuah (LORD) to his anointed, to Cyrus, whose right hand I have holden, to subdue nations before him* (Isaiah 45:1); *I have raised him up in righteousness... he shall build my city, and he shall let go my captives, not for price nor reward* (45:13). And history records the word coming true to the letter: *Now in the first year of Cyrus king of Persia, that the word of Yahuah (LORD) by the mouth of Jeremiah might be fulfilled, Yahuah (LORD) stirred up the spirit of Cyrus king of Persia... that he made a proclamation* (Ezra 1:1), the king himself declaring *Yahuah Elohim (The LORD God) of heaven... hath charged me to build him an house at Jerusalem, which is in Yahudah (Judah)* (Ezra 1:2). A pagan king, named generations before, is raised as Yahuah''s shepherd-instrument — to free the captives and lay the temple''s foundation. Yahuah moves even a heathen throne to perform all his pleasure.',
       sv.verse_id, ev.verse_id, 'free', 27087
  FROM _s303_isa44_lookup sv, _s303_isa44_lookup ev
 WHERE sv.edition_slug='canon' AND sv.book_slug='isaiah' AND sv.chapter_number=44 AND sv.verse_number=28
   AND ev.edition_slug='canon' AND ev.book_slug='isaiah' AND ev.chapter_number=44 AND ev.verse_number=28
ON CONFLICT (slug) DO NOTHING;

